def url(path,prefix): return prefix + path

def head(title,description,prefix):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1018"><meta name="description" content="{esc(description)}"><title>{esc(title)} — Hugo Wei</title><link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/styles.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet"></head><body>'''

def nav(prefix,active=''):
 links=[('index.html','Home','home'),('research/index.html','Research','research'),('research/lab.html','Lab','lab'),('archive/index.html','Archive','archive'),('about/index.html','About','about')]
 a=''.join(f'<a href="{url(path,prefix)}" class="{"is-active" if k==active else ""}">{text}</a>' for path,text,k in links)
 return f'''<a href="#main" class="skip">Skip to content</a><header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix}index.html" aria-label="Hugo Wei home"><span class="brand-symbol">H<span class="brand-dot">.</span>W</span><span class="brand-word">RESEARCH / <em>PORTFOLIO</em></span></a><nav class="nav" aria-label="Main navigation">{a}</nav><a class="header-link" href="https://github.com/HugoWEI" target="_blank" rel="noopener">GitHub <span aria-hidden="true">↗</span></a><button class="mobile-menu" aria-label="Toggle menu" aria-expanded="false" type="button">☰</button></div></header>'''

def footer(prefix):
 return f'''<footer class="footer"><div class="container footer-inner"><div><a class="footer-mark" href="{prefix}index.html">HUGO WEI<span> / RESEARCH</span></a><p>Questions worth being precise about.</p></div><div class="footer-right"><a href="{prefix}research/index.html">Research</a><a href="{prefix}archive/index.html">Archive</a><a href="https://github.com/HugoWEI" target="_blank" rel="noopener">GitHub ↗</a><span class="footer-meta">© 2026 Hugo Wei · Independent research portfolio</span></div></div></footer><script src="{prefix}assets/app.js" defer></script></body></html>'''

def layout(title,desc,prefix,active,body): return head(title,desc,prefix)+nav(prefix,active)+f'<main id="main">{body}</main>'+footer(prefix)

def eyebrow(left,right=''):
 return f'<div class="eyebrow"><span><i class="blink-dot"></i>{left}</span><span>{right}</span></div>'

def project_card(p,prefix='',narrow=False):
 return f'''<a href="{prefix}research/{p['slug']}.html" class="project-card {'card-small' if narrow else ''}"><div class="card-top"><span>{p['index']} / {esc(p['category'])}</span><span class="card-arrow">↗</span></div><div class="glyph" aria-hidden="true">{p['motif']}</div><h3>{esc(p['title'])}</h3><p>{esc(p['short'])}</p><div class="card-bottom"><span class="status-dot"></span>{esc(p['phase'])}</div></a>'''

